import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import"./chunks/assets.B25yjHWQ.js";var i=JSON.parse(`{"title":"动作指引","description":"力量训练入门与动作指引","frontmatter":{"title":"动作指引","description":"力量训练入门与动作指引","date":"2026-05-29T00:00:00.000Z","category":"健康健身","tags":["力量训练"],"order":1},"headers":[],"relativePath":"articles/fitness/strength/start.md","filePath":"articles/fitness/strength/start.md","articleMeta":{"updated":"2026-05-29","words":818,"minutes":2}}`),a={name:`articles/fitness/strength/start.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h2 id="_1-手机端app" tabindex="-1">1. 手机端APP <a class="header-anchor" href="#_1-手机端app" aria-label="Permalink to “1. 手机端APP”">​</a></h2><p>有一个简单易懂又有系统化训练的APP可以事半功倍。手机端推荐“训记”。</p><p>使用一周下来，对该APP爱不释手。训记APP需要购买会员（买断制88元），不需要续费订阅。包含了训练计划、训练讲解、统计对比、饮食记录等功能。训练计划可以高度自定义，也可以使用官网预设的训练组合。</p><p>结合我自身的需求，我选择了官方计划-上下二分化训练，官方制作了<a href="https://www.bilibili.com/video/BV1mt4y1g7v7/?spm_id_from=333.999.0.0&amp;vd_source=df3065b1c93897e7fefbef39806ba46c" target="_blank" rel="noreferrer">视频介绍</a>，具体要点包括：</p><ul><li>二分化把身体区分为“躯干”和“肩腿”</li><li>第一阶段：一周四练，两分化各训练两次，训练5-6个月；第二阶段：一周五练，添加一个部位的增强训练。</li><li>配合饮食。</li></ul><p>如果想选择适合自己的训练计划，可以查看训记作者的微信公众号文章-<a href="https://mp.weixin.qq.com/s/rFA2TLSQixzMj4oTqAPDqg" target="_blank" rel="noreferrer">训记APP的计划选择与说明</a>。</p><h2 id="_2-网页-肌肉维基" tabindex="-1">2. 网页-肌肉维基 <a class="header-anchor" href="#_2-网页-肌肉维基" aria-label="Permalink to “2. 网页-肌肉维基”">​</a></h2><p><img src="/images/image-20260427230546341260427.webp" alt="image-20260427230546341" width="3742" height="1944"></p><p>访问地址：<a href="https://musclewiki.com/zh-cn" target="_blank" rel="noreferrer">https://musclewiki.com/zh-cn</a></p><h2 id="_3-居家训练基础装备-杠铃、哑铃组合" tabindex="-1">3. 居家训练基础装备：杠铃、哑铃组合 <a class="header-anchor" href="#_3-居家训练基础装备-杠铃、哑铃组合" aria-label="Permalink to “3. 居家训练基础装备：杠铃、哑铃组合”">​</a></h2><p>对于我选择的训练计划，训记APP给出了三个训练版本，分别为健身房、杠铃-哑铃组合、哑铃。其中杠铃-哑铃组合的效果竟然约等于健身房，那自然选择该版本，非常契合我想在家训练的想法。</p><p>一套迪卡侬的杠铃+哑铃组合，再来一台哑铃凳，装备就齐全了！这套迪卡侬的官方售价1900+，但是遇到了有缘分的同行，购入二手价格非常巴适。收到货后，用料非常扎实，快拆设计也很便捷。</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};